def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    bg = background(g)

    # colour of each residue class of (x+y) mod 3, read from the input stripes
    colour_of = {}
    for y in range(h):
        for x in range(w):
            c = g[y, x]
            if c != bg:
                colour_of.setdefault((x + y) % 3, int(c))

    out = g.copy()
    for r in range(3):
        if r not in colour_of:
            continue
        for y in range(h):
            for x in range(w):
                if (x + y) % 3 == r:
                    out[y, x] = colour_of[r]
        emit(out, f"Extend every anti-diagonal with (x+y) mod 3 == {r} across the whole grid in colour {colour_of[r]}")

    emit(out, "All three stripe families filled: the period-3 diagonal pattern covers the grid")
    return out
